#pragma once
#include <cstdint>
#include <algorithm>

namespace skyline::gpu::diagnostic {
    // Subtraction avoids wraparound when checking an untrusted descriptor range.
    constexpr bool ScalarRangeValid(std::uint64_t size, std::uint64_t offset) {
        return offset <= size && size - offset >= 4;
    }

    // Quick-bind copies generated by this renderer preserve binding/array identity.
    // Refuse to infer provenance for a remapping or a cross-binding copy.
    constexpr bool IdentityCopyCovers(std::uint32_t binding, std::uint32_t element,
                                      std::uint32_t srcBinding, std::uint32_t srcElement,
                                      std::uint32_t dstBinding, std::uint32_t dstElement,
                                      std::uint32_t count) {
        return binding == srcBinding && binding == dstBinding &&
               srcElement == dstElement && element >= srcElement &&
               element - srcElement < count;
    }

    template<typename Slots, typename Copies>
    void UpdateScalarProvenance(Slots &current, const Slots &writes, const Copies &copies) {
        for (std::size_t i{}; i < current.size(); ++i) {
            const auto &previous{current[i]};
            const bool copied{previous.info && std::any_of(copies.begin(), copies.end(), [&](const auto &copy) {
                return IdentityCopyCovers(previous.binding, previous.element, copy.srcBinding,
                    copy.srcArrayElement, copy.dstBinding, copy.dstArrayElement, copy.descriptorCount);
            })};
            if (writes[i].info)
                current[i] = writes[i];
            else if (!copied)
                current[i] = {};
        }
    }
}
